const data=$input.first().json;
const fields=['fullName','personalEmail','companyEmail','department','role','manager','startDate'];
const e={};const errors=[];
for(const k of fields){e[k]=typeof data.employee?.[k]==='string'?data.employee[k].trim():'';if(!e[k])errors.push('Pflichtfeld fehlt: '+k);if(e[k].length>160)errors.push('Angabe zu lang: '+k);}
for(const k of ['personalEmail','companyEmail'])if(e[k]&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e[k]))errors.push('E-Mail ungültig: '+k);
const date=new Date(e.startDate+'T12:00:00Z');
if(!/^\d{4}-\d{2}-\d{2}$/.test(e.startDate)||!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==e.startDate)errors.push('Startdatum ist ungültig.');
e.managerial=data.employee?.managerial===true;
const warnings=[];
if(Number.isFinite(date.getTime())){if([0,6].includes(date.getUTCDay()))warnings.push('Startdatum liegt am Wochenende. HR muss den Termin prüfen.');if(e.startDate<new Date().toISOString().slice(0,10))warnings.push('Startdatum liegt in der Vergangenheit. Fristen prüfen.');}
if(e.managerial&&e.department.toLowerCase()==='marketing')warnings.push('Die Marketing-Checkliste gilt nur für Rollen ohne Führungsverantwortung. Eine individuelle Ergänzung ist nötig.');
return [{json:{runId:data.runId,employee:e,valid:errors.length===0,errors,warnings,source:'Train-Today-Onboarding-Checklists.pdf · Seiten 1–2'}}];

const data=$input.first().json;
function businessDate(offset){const d=new Date(data.employee.startDate+'T12:00:00Z');let n=Math.abs(offset);const sign=Math.sign(offset);while(n){d.setUTCDate(d.getUTCDate()+sign);if(![0,6].includes(d.getUTCDay()))n--;}return d.toISOString().slice(0,10);}
const tasks=data.checklist.map(t=>({...t,due:businessDate(t.offset),status:'Entwurf',deadlineAssumption:!['G15','G16','G19','G20','M07','M12','M13'].includes(t.id)}));
const openQuestions=['Uhrzeit und Treffpunkt am ersten Tag bestätigen.','Kalenderverfügbarkeit mit HR, CEO und Führungskraft abstimmen.','HR prüft Adresse, Vertrag, Urlaubstage, Notfallkontakt und Originaldokumente in Personio.'];
if(data.employee.department.toLowerCase()==='marketing'&&!data.employee.managerial)openQuestions.push('Buddy und gültigen Link zu den Brand Guidelines bestätigen.');
return [{json:{...data,checklist:undefined,tasks,openQuestions,assumptions:['Fristen ohne Vorgabe sind Vorschläge. Berechnung: Montag–Freitag, keine Feiertage.','Erste Woche: Startdatum + 4 Arbeitstage; Check-ins nach 5 bzw. 10 Arbeitstagen.','Keine Personio-, Slack-, Kalender- oder E-Mail-Aktion wird in diesem Prototyp ausgeführt.']}}];

const plan=$('Aufgaben und Fristen planen').first().json;
const result=$input.first().json;let draft,aiUsed=false,aiError='';
try{const s=result.text;const x=typeof s==='string'?JSON.parse(s.replace(/^```(?:json)?\s*|\s*```$/g,'')):result;if(typeof x.subject!=='string'||typeof x.body!=='string'||x.subject.length<5||x.subject.length>200||x.body.length<60||x.body.length>6000)throw new Error('KI-Antwort hat kein gültiges Format');draft={subject:x.subject,body:x.body};aiUsed=true;}catch{aiError='KI-Ergebnis nicht nutzbar. Regelbasierter Ersatzentwurf: besonders sorgfältig prüfen.';draft={subject:'Willkommen bei Train Today',body:'Hallo [NAME],

herzlich willkommen bei Train Today! Dein Start ist am [STARTDATUM]. Wir freuen uns auf die Zusammenarbeit. Am ersten Tag lernst du dein Team kennen. Uhrzeit und Treffpunkt teilen wir dir nach der Abstimmung mit HR mit.

Bei Fragen wende dich bitte an [FUEHRUNGSKRAFT].

Viele Grüße
Dein HR-Team'};}
for(const k of ['subject','body'])draft[k]=draft[k].replaceAll('[NAME]',plan.employee.fullName).replaceAll('[STARTDATUM]',plan.employee.startDate).replaceAll('[FUEHRUNGSKRAFT]',plan.employee.manager);
return [{json:{...plan,draft,aiUsed,aiError,quality:{formatValid:true,humanReviewRequired:true,note:'Die Formatprüfung bestätigt keine inhaltliche Richtigkeit. HR prüft alle Aussagen.'}}}];
